#include "Game/FpsComponents.h"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace FpsGame { namespace {
Engine::Vector2 Normalize(Engine::Vector2 v){float n=std::sqrt(v.x*v.x+v.y*v.y);return n>0.0001f?Engine::Vector2{v.x/n,v.y/n}:Engine::Vector2{};}
std::uint32_t NextRandom(std::uint32_t& state){state^=state<<13;state^=state>>17;state^=state<<5;return state;}
float RandomUnit(std::uint32_t& state){return float(NextRandom(state)&0x00ffffffu)/16777215.0f;}
void Check(std::uint32_t v){if(v!=1)throw std::runtime_error("Unsupported BallisticBreach component state version");}
}
bool PlayerController::ConsumeShot(){if(!shot_)return false;shot_=false;return true;}
void PlayerController::Update(float dt){auto* e=GetOwner().Resolve();if(!e)return;yaw_+=yawDelta_;pitch_=std::clamp(pitch_+pitchDelta_,-1.25f,1.25f);yawDelta_=pitchDelta_=0;cooldown_=std::max(0.0f,cooldown_-dt);const float s=std::sin(yaw_),c=std::cos(yaw_);Engine::Vector2 forward{s,c},right{c,-s};e->transform.position+=forward*(move_.y*6.2f*dt)+right*(move_.x*6.2f*dt);e->transform.position.x=std::clamp(e->transform.position.x,-38.0f,38.0f);e->transform.position.y=std::clamp(e->transform.position.y,-38.0f,38.0f);move_={};if(fire_&&cooldown_<=0&&!shot_){shot_=true;cooldown_=.24f;}fire_=false;}
void PlayerController::SaveState(StateWriter&w)const{w.Value(move_);w.Value(yaw_);w.Value(pitch_);w.Value(yawDelta_);w.Value(pitchDelta_);w.Value(cooldown_);w.Value(fire_);w.Value(shot_);}
void PlayerController::LoadState(StateReader&r,std::uint32_t v){Check(v);move_=r.Value<Engine::Vector2>();yaw_=r.Value<float>();pitch_=r.Value<float>();yawDelta_=r.Value<float>();pitchDelta_=r.Value<float>();cooldown_=r.Value<float>();fire_=r.Value<bool>();shot_=r.Value<bool>();}
bool BotBrain::ConsumeShot(Engine::Vector2&d){if(!shot_)return false;d=shotDirection_;shot_=false;return true;}
void BotBrain::Update(float dt){cooldown_-=dt;shootPause_=std::max(0.0f,shootPause_-dt);auto* e=GetOwner().Resolve();const auto*t=target_.Resolve();if(!e||!t)return;Engine::Vector2 toTarget{t->transform.position.x-e->transform.position.x,t->transform.position.y-e->transform.position.y};const float distance=std::sqrt(toTarget.x*toTarget.x+toTarget.y*toTarget.y);if(distance<27&&cooldown_<=0&&!shot_&&shootPause_<=0){shotDirection_=Normalize(toTarget);facing_=shotDirection_;shot_=true;cooldown_=1.25f;shootPause_=.55f;animationPhase_=0;}if(shootPause_>0){facing_=Normalize(toTarget);return;}waypointTimer_-=dt;Engine::Vector2 toWaypoint{waypoint_.x-e->transform.position.x,waypoint_.y-e->transform.position.y};if(waypointTimer_<=0||std::sqrt(toWaypoint.x*toWaypoint.x+toWaypoint.y*toWaypoint.y)<1.4f){const float angle=RandomUnit(rngState_)*6.2831853f;const float radius=10.0f+RandomUnit(rngState_)*15.0f;waypoint_={t->transform.position.x+std::sin(angle)*radius,t->transform.position.y+std::cos(angle)*radius};waypointTimer_=2.5f+RandomUnit(rngState_)*3.5f;toWaypoint={waypoint_.x-e->transform.position.x,waypoint_.y-e->transform.position.y};}facing_=Normalize(toWaypoint);if(facing_.x*facing_.x+facing_.y*facing_.y>.5f){e->transform.position+=facing_*(4.2f*dt);animationPhase_+=dt*14.0f;if(animationPhase_>=6.2831853f)animationPhase_-=6.2831853f;}}
void BotBrain::SaveState(StateWriter&w)const{w.Value(target_.GetID());w.Value(cooldown_);w.Value(shotDirection_);w.Value(shot_);w.Value(animationPhase_);w.Value(waypoint_);w.Value(facing_);w.Value(waypointTimer_);w.Value(rngState_);w.Value(shootPause_);}
void BotBrain::LoadState(StateReader&r,std::uint32_t v){if(v<1||v>4)throw std::runtime_error("Unsupported BallisticBreach BotBrain state version");target_=ObjectRef<Engine::Gameplay::Entity>(r.Value<Engine::Gameplay::ObjectID>());cooldown_=r.Value<float>();shotDirection_=r.Value<Engine::Vector2>();shot_=r.Value<bool>();animationPhase_=v>=2?r.Value<float>():0.0f;if(v>=3){waypoint_=r.Value<Engine::Vector2>();facing_=r.Value<Engine::Vector2>();waypointTimer_=r.Value<float>();rngState_=r.Value<std::uint32_t>();if(!rngState_)rngState_=1;}else{waypoint_={};facing_={0,1};waypointTimer_=0;rngState_=1;}shootPause_=v>=4?r.Value<float>():0.0f;}
void Vitality::SaveState(StateWriter&w)const{w.Value(faction_);w.Value(hp_);} void Vitality::LoadState(StateReader&r,std::uint32_t v){Check(v);faction_=r.Value<Faction>();hp_=r.Value<int>();}
void BallisticFlight::Update(float dt){auto*e=GetOwner().Resolve();if(!e)return;e->transform.position+=velocity_*dt;height_+=verticalSpeed_*dt;verticalSpeed_-=9.8f*dt;lifetime_-=dt;}
void BallisticFlight::SaveState(StateWriter&w)const{w.Value(velocity_);w.Value(height_);w.Value(verticalSpeed_);w.Value(lifetime_);w.Value(faction_);} void BallisticFlight::LoadState(StateReader&r,std::uint32_t v){Check(v);velocity_=r.Value<Engine::Vector2>();height_=r.Value<float>();verticalSpeed_=r.Value<float>();lifetime_=r.Value<float>();faction_=r.Value<Faction>();}
}
